'use strict';
(()=>{
  const escape=value=>String(value||'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
  function xml(title,url,entries){return '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>'+escape(title)+'</title><link>'+escape(url)+'</link><description>Generated by Open Sesame from links on '+escape(url)+'</description>'+entries.map(e=>'<item><guid isPermaLink="'+(e.url?'true':'false')+'">'+escape(e.url||e.id||e.title)+'</guid><title>'+escape(e.title)+'</title>'+(e.url?'<link>'+escape(e.url)+'</link>':'')+'<description>'+escape(e.description||'Open the original article to read more.')+'</description>'+(e.date&&Number.isFinite(new Date(e.date).getTime())?'<pubDate>'+new Date(e.date).toUTCString()+'</pubDate>':'')+'</item>').join('')+'</channel></rss>'}
  function extract(html,url,selector=''){
    const doc=new DOMParser().parseFromString(html,'text/html'),base=pageUrl(url);if(!base)throw Error('Use a website URL.');
    const title=doc.title?.trim()||new URL(base).hostname,alternates=[...doc.querySelectorAll('link[rel~="alternate"][href]')].filter(n=>/application\/(rss|atom)\+xml/i.test(n.type)).map(n=>{try{return pageUrl(new URL(n.getAttribute('href'),base).href)}catch{return ''}}).filter(Boolean);
    let nodes;try{nodes=[...doc.querySelectorAll(selector||'article h1 a[href],article h2 a[href],article h3 a[href],h2 a[href],h3 a[href],a[rel="bookmark"]')];if(!nodes.length&&!selector)nodes=[...doc.querySelectorAll('main a[href]')]}catch{throw Error('The article link selector is not valid CSS.')}
    const seen=new Set(),entries=[];
    for(const node of nodes){if(node.closest('nav,footer,aside,script,style')||(node.closest('header')&&!node.closest('article')))continue;const a=node.matches('a[href]')?node:node.querySelector('a[href]');if(!a)continue;let href;try{href=pageUrl(new URL(a.getAttribute('href'),base).href)}catch{continue}if(!href||new URL(href).origin!==new URL(base).origin)continue;const u=new URL(href);u.hash='';href=u.href;const name=a.textContent.trim().replace(/\s+/g,' ');if(name.length<5||href===base||seen.has(href)||/\.(?:png|jpe?g|svg|gif|zip)$/i.test(u.pathname))continue;seen.add(href);const article=a.closest('article'),date=Date.parse(article?.querySelector('time[datetime]')?.getAttribute('datetime')||'')||0;entries.push({url:href,title:name.slice(0,300),description:article?.querySelector('p')?.textContent.trim().slice(0,1000)||'',date});if(entries.length===60)break}
    return {title,url:base,alternates,entries};
  }
  async function generate(url,selector=''){
    const source=await OpenSesameContent.fetchText(url);
    const isFeed=text=>{if(/<!DOCTYPE|<!ENTITY/i.test(text))return false;const doc=new DOMParser().parseFromString(text,'application/xml');return !doc.getElementsByTagName('parsererror').length&&['rss','feed'].includes(doc.documentElement?.localName)};
    if(isFeed(source.text))return {...source,discovered:true};
    const result=extract(source.text,source.url,selector);
    if(!selector)for(const alternate of result.alternates.slice(0,3)){try{const feed=await OpenSesameContent.fetchText(alternate);if(isFeed(feed.text))return {...feed,discovered:true}}catch{/* Fall back to article links if the advertised feed is unavailable. */}}
    if(!result.entries.length)throw Error('No article links found. Try the site’s blog/index page or an article link selector. Pages rendered only by JavaScript need a published feed.');
    return {url:source.url,text:xml(result.title,result.url,result.entries),generated:true};
  }
  window.OpenSesameSiteFeeds={xml,extract,generate};
})();
